module fifo4 (
    input clk,
    input reset,
    input wr_en,
    input rd_en,
    input [7:0] din,
    output reg [7:0] dout,
    output reg full,
    output reg empty,
    output reg [2:0] count
);

    reg [1:0] wr_ptr;
    reg [1:0] rd_ptr;
    reg [7:0] mem [0:3];

    always @(posedge clk) begin
        if (reset) begin
            wr_ptr <= 2'd0;
            rd_ptr <= 2'd0;
            count <= 3'd0;
            full <= 1'b0;
            empty <= 1'b1;
            dout <= 8'd0;
        end else begin
            // Determine if we need to do a write or read
            reg write_happened = 1'b0;
            reg read_happened = 1'b0;
            reg new_full = 1'b0;
            reg new_empty = 1'b0;
            reg new_dout = 8'd0;

            if (wr_en && !empty) begin
                mem[wr_ptr] <= din;
                wr_ptr <= wr_ptr + 1;
                count <= count + 1;
                write_happened = 1'b1;
            end
            if (rd_en && !full) begin
                new_dout <= mem[rd_ptr];
                rd_ptr <= rd_ptr + 1;
                count <= count - 1;
                read_happened = 1'b1;
            end

            // Update full and empty based on new count
            new_full = (count == 3'd4);
            new_empty = (count == 3'd0);

            // Update dout only if a write happened (so it reflects the new data)
            if (write_happened) begin
                dout <= din;
            end else if (read_happened) begin
                dout <= new_dout;
            end else begin
                dout <= dout; // no change
            end

            full <= new_full;
            empty <= new_empty;
        end
    end

endmodule

